async function runStage(stage, ctx) {
    const vars = [];
    for (const [key, val] of Object.entries(ctx.outputs)) {
        vars.push(`\`\`\`\n${key}:\n${val}\n\`\`\``);
    }
    const injected = vars.length > 0
        ? `Previous stage outputs:\n${vars.join('\n\n')}\n\n---\n\n${stage.prompt}`
        : stage.prompt;
    let inputStr = '';
    for (const [k, v] of Object.entries(ctx.inputs)) {
        inputStr += `${k}: ${JSON.stringify(v)}\n`;
    }
    const fullPrompt = `Inputs:\n${inputStr}\n---\n\n${injected}`;
    const result = await ctx.provider.generateText(fullPrompt, {
        system: stage.system,
        complexity: stage.model.includes('M3') ? 'complex' : 'simple',
    });
    return result.text;
}
async function runPipeline(spec, inputs, opts) {
    const outputs = {};
    for (const stage of spec.stages) {
        if (stage.depends_on) {
            for (const dep of stage.depends_on) {
                if (!outputs[dep])
                    throw new Error(`Stage ${stage.id} depends on missing ${dep}`);
            }
        }
        opts.hooks?.onStageStart?.(stage.id);
        const t0 = Date.now();
        const text = await runStage(stage, { provider: opts.provider, inputs, outputs });
        const ms = Date.now() - t0;
        outputs[stage.id] = text;
        opts.hooks?.onStageComplete?.(stage.id, ms, text);
    }
    return outputs;
}


